    wx, wy = _waypoint(x, y)

    # Adjust waypoint for gate passage
    if x > 24.0:
        wy = 4.0
    if x < G1_X + 0.5 and y < 1.2:
        wy = max(wy, 1.3)
    if y < 1.4:
        wy = max(wy, 1.5)
    if G2_X - 1.0 <= x <= G2_X + 2.0 and y < 1.9:
