    if TX_MIN <= x <= TX_MAX and TY_MIN <= y <= TY_MAX:
        # Apply minimal thrust to stay in target zone
        sandbox.apply_thrust(0.0, 75.0)
        return

    # Calculate waypoint
    wx, wy = _waypoint(x, y)

