    if G2_X - 1.0 <= x <= G2_X + 2.0 and y < 1.9:
        wy = max(wy, 2.5)  # Increased vertical clearance for G2
    if 20.5 <= x <= G2_X + 1.0 and y < 1.85:
        wx, wy = x + 0.3, 2.5

    dx = wx - x
    dy = wy - y
    dist = math.sqrt(dx*dx + dy*dy)

    if dist < 1e-6:
        sandbox.apply_thrust(0.0, 75.0)
        return

    ux = dx / dist
    uy = dy / dist

    # Dynamic thrust scaling based on proximity to gates and low-x regions
    thrust_mag = MAX_THRUST
    if x < 20.0:
        # Increase thrust in low-x regions to counteract drag
        thrust_mag = MAX_THRUST * 1.5  # Increased from 1.2 to 1.5
    elif DRAIN_LO <= x <= DRAIN_HI:
