    thrust_mag = math.sqrt(fx*fx + fy*fy)

    # Increase thrust in early stages
    if x < 10.0:
        thrust_mag = min(160.0, thrust_mag)

    # Apply velocity threshold trigger
    if heat >= overheat_limit * HEAT_SAFE_FRAC:
        thrust_mag = min(LOW_THRUST, remaining * 0.25)
    else:
        thrust_mag = min(MAX_THRUST, remaining * 0.35)

    # Adjust for heat safety
    if overheat_limit <= 40000.0:
        heat_frac = heat / overheat_limit
        if heat_frac > 0.3:
            thrust_mag = 40.0
        else:
            thrust_mag = 60.0

    # Scale thrust based on distance to target
    if dist > 50.0:
        thrust_mag = min(MAX_THRUST, thrust_mag * 1.2)
    elif dist > 20.0:
        thrust_mag = min(MAX_THRUST, thrust_mag * 1.1)

    # Apply final thrust
    sandbox.apply_thrust(fx, fy)

